#include <vector>
#include <algorithm>

class Solution {
public:
    int countPyramids(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();

        auto countDirectional = [&](const std::vector<std::vector<int>>& g) -> int {
            std::vector<std::vector<int>> dp = g;
            int total = 0;
            for (int r = m - 2; r >= 0; --r) {
                for (int c = 1; c < n - 1; ++c) {
                    if (g[r][c] == 1) {
                        dp[r][c] = std::min({dp[r + 1][c - 1], dp[r + 1][c], dp[r + 1][c + 1]}) + 1;
                        total += dp[r][c] - 1;
                    }
                }
            }
            return total;
        };

        int normal = countDirectional(grid);
        std::vector<std::vector<int>> revGrid = grid;
        std::reverse(revGrid.begin(), revGrid.end());
        int inverse = countDirectional(revGrid);

        return normal + inverse;
    }
};

class Solution {
    public int countPyramids(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int normal = countDirectional(grid, m, n);

        int[][] revGrid = new int[m][n];
        for (int i = 0; i < m; i++) {
            revGrid[i] = grid[m - 1 - i];
        }
        int inverse = countDirectional(revGrid, m, n);

        return normal + inverse;
    }

    private int countDirectional(int[][] g, int m, int n) {
        int[][] dp = new int[m][n];
        for (int i = 0; i < m; i++) {
            dp[i] = g[i].clone();
        }
        int total = 0;
        for (int r = m - 2; r >= 0; r--) {
            for (int c = 1; c < n - 1; c++) {
                if (g[r][c] == 1) {
                    dp[r][c] = Math.min(dp[r + 1][c - 1], Math.min(dp[r + 1][c], dp[r + 1][c + 1])) + 1;
                    total += dp[r][c] - 1;
                }
            }
        }
        return total;
    }
}

