var countPyramids = function(grid) {
    const m = grid.length, n = grid[0].length;

    const countDirectional = (g) => {
        const dp = g.map(row => [...row]);
        let total = 0;
        for (let r = m - 2; r >= 0; r--) {
            for (let c = 1; c < n - 1; c++) {
                if (g[r][c] === 1) {
                    dp[r][c] = Math.min(dp[r + 1][c - 1], dp[r + 1][c], dp[r + 1][c + 1]) + 1;
                    total += dp[r][c] - 1;
                }
            }
        }
        return total;
    };

    const normal = countDirectional(grid);
    const revGrid = [...grid].reverse();
    const inverse = countDirectional(revGrid);

    return normal + inverse;
};
